package server

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"path"
	"strings"
	"time"

	"github.com/google/uuid"
	"golang.org/x/crypto/bcrypt"
)

func(v *Server)users(w http.ResponseWriter,r *http.Request){uid,ok:=v.sessionUser(r);if !ok||!v.isAdmin(uid){http.Error(w,"forbidden",403);return};switch r.Method{case "GET":rows,e:=v.store.DB.Query(`SELECT id,username,email,display_name,active,created_at FROM users ORDER BY username`);if e!=nil{http.Error(w,"database error",500);return};type userRow struct{id,username,email,name string;active int;created time.Time};items:=[]userRow{};for rows.Next(){var u userRow;if e=rows.Scan(&u.id,&u.username,&u.email,&u.name,&u.active,&u.created);e!=nil{_ = rows.Close();http.Error(w,"database error",500);return};items=append(items,u)};if e=rows.Err();e!=nil{_ = rows.Close();http.Error(w,"database error",500);return};_ = rows.Close();roleMap,groupMap:=map[string][]string{},map[string][]string{};rr,e:=v.store.DB.Query(`SELECT user_id,role FROM user_roles ORDER BY user_id,role`);if e!=nil{http.Error(w,"database error",500);return};for rr.Next(){var id,role string;if e=rr.Scan(&id,&role);e!=nil{_ = rr.Close();http.Error(w,"database error",500);return};roleMap[id]=append(roleMap[id],role)};if e=rr.Err();e!=nil{_ = rr.Close();http.Error(w,"database error",500);return};_ = rr.Close();gr,e:=v.store.DB.Query(`SELECT user_id,group_name FROM user_groups ORDER BY user_id,group_name`);if e!=nil{http.Error(w,"database error",500);return};for gr.Next(){var id,group string;if e=gr.Scan(&id,&group);e!=nil{_ = gr.Close();http.Error(w,"database error",500);return};groupMap[id]=append(groupMap[id],group)};if e=gr.Err();e!=nil{_ = gr.Close();http.Error(w,"database error",500);return};_ = gr.Close();out:=make([]map[string]any,0,len(items));for _,u:=range items{roles:=roleMap[u.id];if roles==nil{roles=[]string{}};groups:=groupMap[u.id];if groups==nil{groups=[]string{}};out=append(out,map[string]any{"id":u.id,"username":u.username,"email":u.email,"display_name":u.name,"active":u.active==1,"roles":roles,"groups":groups,"created_at":u.created})};writeJSON(w,200,out)
	case "POST":var in struct{Username string `json:"username"`;Email string `json:"email"`;Password string `json:"password"`;DisplayName string `json:"display_name"`;Roles []string `json:"roles"`;Groups []string `json:"groups"`};if !readJSON(w,r,&in){return};if !validUsername(in.Username)||in.Email==""||len(in.Password)<12{http.Error(w,"username, email and password of at least 12 characters are required",400);return};if len(in.Roles)==0{in.Roles=[]string{"user"}};for _,role:=range in.Roles{if !validRole(role){http.Error(w,"invalid role",400);return}};hash,e:=bcrypt.GenerateFromPassword([]byte(in.Password),12);if e!=nil{http.Error(w,"invalid password",400);return};id:=uuid.NewString();now:=time.Now().UTC();tx,e:=v.store.DB.Begin();if e!=nil{http.Error(w,"database error",500);return};defer tx.Rollback();_,e=tx.Exec(`INSERT INTO users(id,username,email,password,display_name,active,created_at,updated_at) VALUES(?,?,?,?,?,1,?,?)`,id,in.Username,strings.ToLower(in.Email),string(hash),in.DisplayName,now,now);if e==nil{for _,role:=range in.Roles{_,e=tx.Exec(`INSERT INTO user_roles(user_id,role) VALUES(?,?)`,id,role);if e!=nil{break}}};if e==nil{for _,g:=range in.Groups{_,e=tx.Exec(`INSERT INTO user_groups(user_id,group_name) VALUES(?,?)`,id,g);if e!=nil{break}}};if e!=nil{http.Error(w,"user creation failed (duplicate username/email?)",400);return};if e=tx.Commit();e!=nil{http.Error(w,"database error",500);return};writeJSON(w,201,map[string]string{"id":id,"username":in.Username})
	default:method(w)}}

func(v *Server)user(w http.ResponseWriter,r *http.Request){trim:=strings.TrimPrefix(r.URL.Path,"/api/v1/users/");p:=strings.Split(strings.Trim(trim,"/"),"/");if len(p)<1||p[0]==""{http.NotFound(w,r);return};username:=p[0];if len(p)==2&&p[1]=="avatar"{v.avatar(w,r,username);return};uid,ok:=v.sessionUser(r);if !ok{http.Error(w,"unauthorized",401);return};admin:=v.isAdmin(uid);var target string;var name,email string;var active int;e:=v.store.DB.QueryRow(`SELECT id,display_name,email,active FROM users WHERE username=?`,username).Scan(&target,&name,&email,&active);if e!=nil||active!=1{http.NotFound(w,r);return};if !admin&&uid!=target{http.Error(w,"forbidden",403);return};switch {case len(p)==1&&r.Method=="GET":roles,groups:=v.attrs(target);writeJSON(w,200,map[string]any{"id":target,"username":username,"email":email,"display_name":name,"active":true,"roles":roles,"groups":groups})
	case len(p)==1&&r.Method=="PATCH":var in struct{Email *string `json:"email"`;DisplayName *string `json:"display_name"`};if !readJSON(w,r,&in){return};if !admin&&in.Email!=nil{http.Error(w,"only administrators can change email",403);return};if in.Email!=nil{_,e=v.store.DB.Exec(`UPDATE users SET email=?,updated_at=? WHERE id=?`,strings.ToLower(*in.Email),time.Now().UTC(),target)};if e==nil&&in.DisplayName!=nil{_,e=v.store.DB.Exec(`UPDATE users SET display_name=?,updated_at=? WHERE id=?`,*in.DisplayName,time.Now().UTC(),target)};if e!=nil{http.Error(w,"profile update failed",400);return};writeJSON(w,200,map[string]string{"status":"ok"})
	case len(p)==1&&r.Method=="DELETE":if !admin{http.Error(w,"forbidden",403);return};_,e=v.store.DB.Exec(`UPDATE users SET active=0,updated_at=? WHERE id=?`,time.Now().UTC(),target);if e!=nil{http.Error(w,"database error",500);return};writeJSON(w,200,map[string]string{"status":"ok"})
	case len(p)==2&&p[1]=="roles"&&r.Method=="PATCH":if !admin{http.Error(w,"forbidden",403);return};var in struct{Roles []string `json:"roles"`};if !readJSON(w,r,&in){return};for _,x:=range in.Roles{if !validRole(x){http.Error(w,"invalid role",400);return}};tx,_:=v.store.DB.Begin();_,e=tx.Exec(`DELETE FROM user_roles WHERE user_id=?`,target);if e==nil{for _,x:=range in.Roles{_,e=tx.Exec(`INSERT INTO user_roles(user_id,role) VALUES(?,?)`,target,x);if e!=nil{break}}};if e==nil{e=tx.Commit()}else{_ = tx.Rollback()};if e!=nil{http.Error(w,"role update failed",400);return};writeJSON(w,200,map[string]string{"status":"ok"})
	case len(p)==2&&p[1]=="groups"&&r.Method=="PATCH":if !admin{http.Error(w,"forbidden",403);return};var in struct{Groups []string `json:"groups"`};if !readJSON(w,r,&in){return};tx,_:=v.store.DB.Begin();_,e=tx.Exec(`DELETE FROM user_groups WHERE user_id=?`,target);if e==nil{for _,x:=range in.Groups{_,e=tx.Exec(`INSERT INTO user_groups(user_id,group_name) VALUES(?,?)`,target,x);if e!=nil{break}}};if e==nil{e=tx.Commit()}else{_ =tx.Rollback()};if e!=nil{http.Error(w,"group update failed",400);return};writeJSON(w,200,map[string]string{"status":"ok"})
	default:method(w)}}

func(v *Server)avatar(w http.ResponseWriter,r *http.Request,username string){switch r.Method{case "GET":var data []byte;var typ string;e:=v.store.DB.QueryRow(`SELECT avatar,avatar_type FROM users WHERE username=? AND active=1`,username).Scan(&data,&typ);if e!=nil{http.NotFound(w,r);return};if len(data)>0{w.Header().Set("Content-Type",typ);w.Header().Set("Cache-Control","public, max-age=300");_,_=w.Write(data);return};w.Header().Set("Content-Type","image/svg+xml");w.WriteHeader(200);_,_=fmt.Fprint(w,`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96"><rect width="96" height="96" rx="48" fill="#dbeafe"/><circle cx="48" cy="36" r="18" fill="#2563eb"/><path d="M14 90c3-21 16-32 34-32s31 11 34 32" fill="#2563eb"/></svg>`)
	case "PUT":uid,ok:=v.sessionUser(r);if !ok{http.Error(w,"unauthorized",401);return};var target string;_ =v.store.DB.QueryRow(`SELECT id FROM users WHERE username=? AND active=1`,username).Scan(&target);if target==""||uid!=target&&!v.isAdmin(uid){http.Error(w,"forbidden",403);return};r.Body=http.MaxBytesReader(w,r.Body,256*1024);data,e:=ioReadAll(r);if e!=nil{http.Error(w,"avatar exceeds 256KB",413);return};typ:=http.DetectContentType(data);if typ!="image/png"&&typ!="image/jpeg"{http.Error(w,"PNG or JPEG required",415);return};if typ=="image/png"&&!validPNG(data)||typ=="image/jpeg"&&!validJPEG(data){http.Error(w,"invalid image",415);return};_,e=v.store.DB.Exec(`UPDATE users SET avatar=?,avatar_type=?,updated_at=? WHERE id=?`,data,typ,time.Now().UTC(),target);if e!=nil{http.Error(w,"database error",500);return};w.WriteHeader(204)
	default:method(w)}}

func(v *Server)clients(w http.ResponseWriter,r *http.Request){uid,ok:=v.sessionUser(r);if !ok||!v.isAdmin(uid){http.Error(w,"forbidden",403);return};switch r.Method{case "GET":rows,e:=v.store.DB.Query(`SELECT id,name,redirect_uris,allowed_scopes,grant_types,created_at FROM oidc_clients ORDER BY id`);if e!=nil{http.Error(w,"database error",500);return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,n,a,b,c string;var t time.Time;_ =rows.Scan(&id,&n,&a,&b,&c,&t);out=append(out,map[string]any{"client_id":id,"name":n,"redirect_uris":parseJSONList(a),"allowed_scopes":parseJSONList(b),"grant_types":parseJSONList(c),"created_at":t})};writeJSON(w,200,out)
	case "POST":var in struct{ClientID string `json:"client_id"`;ClientSecret string `json:"client_secret"`;Name string `json:"name"`;RedirectURIs []string `json:"redirect_uris"`;AllowedScopes []string `json:"allowed_scopes"`;GrantTypes []string `json:"grant_types"`};if !readJSON(w,r,&in){return};if in.ClientID==""||len(in.ClientSecret)<24||in.Name==""||len(in.RedirectURIs)==0{http.Error(w,"client_id, name, redirect_uris and 24+ character secret required",400);return};for _,u:=range in.RedirectURIs{if !ensureURL(u){http.Error(w,"redirect URIs must be absolute URLs",400);return}};for _,g:=range in.GrantTypes{if g!="authorization_code"&&g!="refresh_token"{http.Error(w,"unsupported grant type",400);return}};for _,scope:=range in.AllowedScopes{if scope!="openid"&&scope!="profile"&&scope!="email"&&scope!="roles"&&scope!="groups"{http.Error(w,"unsupported scope",400);return}};h,e:=bcrypt.GenerateFromPassword([]byte(in.ClientSecret),12);if e!=nil{http.Error(w,"invalid secret",400);return};if len(in.AllowedScopes)==0{in.AllowedScopes=[]string{"openid","profile","email"}};if len(in.GrantTypes)==0{in.GrantTypes=[]string{"authorization_code","refresh_token"}};_,e=v.store.DB.Exec(`INSERT INTO oidc_clients(id,secret_hash,name,redirect_uris,allowed_scopes,grant_types,created_at) VALUES(?,?,?,?,?,?,?)`,in.ClientID,string(h),in.Name,stringJSON(in.RedirectURIs),stringJSON(in.AllowedScopes),stringJSON(in.GrantTypes),time.Now().UTC());if e!=nil{http.Error(w,"client creation failed",400);return};writeJSON(w,201,map[string]any{"client_id":in.ClientID,"client_secret":in.ClientSecret})
	default:method(w)}}
func(v *Server)client(w http.ResponseWriter,r *http.Request){uid,ok:=v.sessionUser(r);if !ok||!v.isAdmin(uid){http.Error(w,"forbidden",403);return};id:=path.Base(r.URL.Path);if id=="clients"||id==""{http.NotFound(w,r);return};switch r.Method{case "GET":var n,a,b,c string;e:=v.store.DB.QueryRow(`SELECT name,redirect_uris,allowed_scopes,grant_types FROM oidc_clients WHERE id=?`,id).Scan(&n,&a,&b,&c);if e!=nil{http.NotFound(w,r);return};writeJSON(w,200,map[string]any{"client_id":id,"name":n,"redirect_uris":parseJSONList(a),"allowed_scopes":parseJSONList(b),"grant_types":parseJSONList(c)})
	case "PATCH":var in struct{Name *string `json:"name"`;RedirectURIs *[]string `json:"redirect_uris"`;AllowedScopes *[]string `json:"allowed_scopes"`;GrantTypes *[]string `json:"grant_types"`;ClientSecret *string `json:"client_secret"`};if !readJSON(w,r,&in){return};var e error;if in.Name!=nil{_,e=v.store.DB.Exec(`UPDATE oidc_clients SET name=? WHERE id=?`,*in.Name,id)};if e==nil&&in.RedirectURIs!=nil{for _,u:=range *in.RedirectURIs{if !ensureURL(u){http.Error(w,"invalid redirect URI",400);return}};_,e=v.store.DB.Exec(`UPDATE oidc_clients SET redirect_uris=? WHERE id=?`,stringJSON(*in.RedirectURIs),id)};if e==nil&&in.AllowedScopes!=nil{_,e=v.store.DB.Exec(`UPDATE oidc_clients SET allowed_scopes=? WHERE id=?`,stringJSON(*in.AllowedScopes),id)};if e==nil&&in.GrantTypes!=nil{_,e=v.store.DB.Exec(`UPDATE oidc_clients SET grant_types=? WHERE id=?`,stringJSON(*in.GrantTypes),id)};if e==nil&&in.ClientSecret!=nil{h,_:=bcrypt.GenerateFromPassword([]byte(*in.ClientSecret),12);_,e=v.store.DB.Exec(`UPDATE oidc_clients SET secret_hash=? WHERE id=?`,string(h),id)};if e!=nil{http.Error(w,"client update failed",400);return};writeJSON(w,200,map[string]string{"status":"ok"})
	case "DELETE":_,e:=v.store.DB.Exec(`DELETE FROM oidc_clients WHERE id=?`,id);if e!=nil{http.Error(w,"client has active data or was not found",409);return};writeJSON(w,200,map[string]string{"status":"ok"})
	default:method(w)}}
func(v *Server)attrs(id string)([]string,[]string){roles,groups:=[]string{},[]string{};rows,e:=v.store.DB.Query(`SELECT role FROM user_roles WHERE user_id=? ORDER BY role`,id);if e==nil{for rows.Next(){var s string;if rows.Scan(&s)==nil{roles=append(roles,s)}};_ = rows.Close()};rows,e=v.store.DB.Query(`SELECT group_name FROM user_groups WHERE user_id=? ORDER BY group_name`,id);if e==nil{for rows.Next(){var s string;if rows.Scan(&s)==nil{groups=append(groups,s)}};_ = rows.Close()};return roles,groups}
func validUsername(s string)bool{if s==""||len(s)>64{return false};for _,r:=range s{if !(r>='a'&&r<='z'||r>='A'&&r<='Z'||r>='0'&&r<='9'||r=='_'||r=='-'){return false}};return true}
func validRole(s string)bool{return s=="admin"||s=="user"||s=="viewer"}
func validPNG(b []byte)bool{return len(b)>=8&&string(b[:8])=="\x89PNG\r\n\x1a\n"}
func validJPEG(b []byte)bool{return len(b)>=4&&b[0]==0xff&&b[1]==0xd8&&b[len(b)-2]==0xff&&b[len(b)-1]==0xd9}
func ioReadAll(r *http.Request)([]byte,error){return io.ReadAll(r.Body)}
var _=json.Valid
